const SAVE_KEY='emberfall-save-v1', BOARD_KEY='emberfall-board-v1';
const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');
const W=960,H=540, keys=new Set(), heldDirs=new Set();
const ui={hpText:document.getElementById('hpText'),hpFill:document.getElementById('hpFill'),wardText:document.getElementById('wardText'),wardFill:document.getElementById('wardFill'),damage:document.getElementById('damageStat'),speed:document.getElementById('speedStat'),kills:document.getElementById('killsStat'),score:document.getElementById('scoreStat'),level:document.getElementById('levelBadge'),xpText:document.getElementById('xpText'),xpFill:document.getElementById('xpFill'),wave:document.getElementById('waveNumber'),waveSmall:document.getElementById('waveSmall'),enemies:document.getElementById('enemySmall'),waveEnemies:document.getElementById('waveEnemies'),killsHud:document.getElementById('killsHud'),runWave:document.getElementById('runWave'),runTime:document.getElementById('runTime'),bestWave:document.getElementById('bestWave'),status:document.getElementById('gameStatus'),modal:document.getElementById('modalBackdrop'),modalContent:document.getElementById('modalContent'),msg:document.getElementById('battleMsg'),toast:document.getElementById('toast'),leader:document.getElementById('leaderRows'),save:document.getElementById('saveText'),objective:document.getElementById('objective')};
let player, enemies=[], particles=[], wave=1, kills=0, score=0, elapsed=0, level=1, xp=0, runNumber=1, bestWave=0, gameOver=false, paused=false, spawnLeft=0, spawnTimer=0, waveWait=0, attackCooldown=0, swing=0, swingHit=false, dashCooldown=0, dashTime=0, flash=0, savedAt=0, lastFrame=0, autosaveAt=0, msgTimer=0, soundOn=true, audioCtx=null, toastTimer=0;
const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function freshGame(){player={x:480,y:278,r:19,hp:100,maxHp:100,damage:12,speed:190,dir:0.6,invuln:0};enemies=[];particles=[];wave=1;kills=0;score=0;elapsed=0;level=1;xp=0;gameOver=false;paused=false;spawnLeft=4;spawnTimer=.7;waveWait=0;attackCooldown=.3;swing=0;swingHit=false;dashCooldown=0;dashTime=0;flash=0;runNumber=Number(runNumber)||1;for(let i=0;i<3;i++)spawnEnemy();ui.modal.classList.remove('show');updateUI();saveGame();}
function loadGame(){try{const raw=localStorage.getItem(SAVE_KEY);if(!raw)return false;const s=JSON.parse(raw);if(!s||s.version!==1||!s.player)return false;player={...s.player};enemies=Array.isArray(s.enemies)?s.enemies:[];particles=[];wave=s.wave||1;kills=s.kills||0;score=s.score||0;elapsed=s.elapsed||0;level=s.level||1;xp=s.xp||0;runNumber=s.runNumber||1;bestWave=s.bestWave||0;gameOver=!!s.gameOver;spawnLeft=s.spawnLeft||0;spawnTimer=s.spawnTimer||0;waveWait=s.waveWait||0;updateUI();if(gameOver)showDeathModal(true);toast('Welcome back, Warden.');return true}catch(e){console.warn('Save could not be loaded',e);return false}}
function saveGame(){try{const state={version:1,player,enemies:enemies.map(e=>({...e})),wave,kills,score,elapsed,level,xp,runNumber,bestWave,gameOver,spawnLeft,spawnTimer,waveWait};localStorage.setItem(SAVE_KEY,JSON.stringify(state));savedAt=Date.now();ui.save.textContent='SAVED JUST NOW';setTimeout(()=>{if(Date.now()-savedAt>1800)ui.save.textContent='AUTO-SAVE READY'},1900)}catch(e){ui.save.textContent='SAVE UNAVAILABLE';console.warn(e)}}
function getBoard(){try{return JSON.parse(localStorage.getItem(BOARD_KEY)||'[]')}catch{return[]}}
function setBoard(list){try{localStorage.setItem(BOARD_KEY,JSON.stringify(list.slice(0,8)))}catch{}}
function recordRun(){const board=getBoard();board.push({name:'Ash Rowan',score,kills,wave,time:Math.floor(elapsed),date:Date.now()});board.sort((a,b)=>b.score-a.score);setBoard(board);bestWave=Math.max(bestWave,wave);runNumber++;}
function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function showMessage(text){ui.msg.textContent=text;ui.msg.classList.add('show');msgTimer=1.5}
function timeText(seconds){const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
function updateUI(){if(!player)return;ui.hpText.textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;ui.hpFill.style.width=`${clamp(player.hp/player.maxHp*100,0,100)}%`;ui.wardText.textContent=dashCooldown<=0?'READY':`${Math.ceil((1-dashCooldown/3.5)*100)}%`;ui.wardFill.style.width=`${clamp((1-dashCooldown/3.5)*100,0,100)}%`;ui.damage.textContent=player.damage;ui.speed.textContent=(player.speed/60).toFixed(1);ui.kills.textContent=kills;ui.score.textContent=score.toLocaleString();ui.level.textContent=level;ui.xpText.textContent=`${xp} / ${level*5}`;ui.xpFill.style.width=`${xp/(level*5)*100}%`;ui.wave.textContent=String(wave).padStart(2,'0');ui.waveSmall.textContent=String(wave).padStart(2,'0');ui.enemies.textContent=enemies.length+spawnLeft;ui.waveEnemies.textContent=enemies.length+spawnLeft;ui.killsHud.textContent=kills;ui.runWave.textContent=wave;ui.runTime.textContent=timeText(elapsed);ui.bestWave.textContent=bestWave?`NIGHT ${bestWave}`:'—';ui.status.textContent=gameOver?'THE LANTERN FELL':paused?'RESTING BY THE FIRE':`NIGHT ${String(wave).padStart(2,'0')} · HOLD THE CLEARING`;ui.objective.innerHTML=spawnLeft||enemies.length?`Defeat the wraiths <span>✦ ${enemies.length+spawnLeft}</span>`:'The clearing is quiet <span>✦</span>';renderBoard()}
function renderBoard(){const list=getBoard().slice(0,5),current={name:'ASH · THIS RUN',score,kills,wave,current:true};if(!gameOver||score>0)list.push(current);list.sort((a,b)=>b.score-a.score);const top=list.slice(0,5);if(!top.length){ui.leader.innerHTML='<div style="padding:16px 3px;color:#909284;font-size:11px;line-height:1.55">Your first legend is unwritten.<br>Survive the night to earn your place.</div>';return}ui.leader.innerHTML=top.map((r,i)=>`<div class="leader-row ${r.current?'you-row':''}"><span class="rank ${i===0?'first':''}">${String(i+1).padStart(2,'0')}</span><div><div class="leader-name">${r.current?'ASH · THIS RUN':escapeHtml(r.name||'Ash Rowan')}</div><div class="leader-meta">NIGHT ${String(r.wave||1).padStart(2,'0')} · ${r.kills||0} SOULS</div></div><div class="leader-score">${Number(r.score||0).toLocaleString()}</div></div>`).join('')}
function escapeHtml(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function spawnEnemy(){if(enemies.length>12)return;const side=Math.floor(Math.random()*4);let x,y;if(side===0){x=rand(45,915);y=rand(45,75)}else if(side===1){x=rand(45,915);y=rand(465,500)}else if(side===2){x=rand(45,80);y=rand(90,450)}else{x=rand(880,915);y=rand(90,450)}const elite=(wave>=3&&Math.random()<Math.min(.4,.1+wave*.015));const type=elite?'brute':Math.random()<.25?'wisp':'wraith';const scale=1+Math.min(wave-1,15)*.09;enemies.push({x,y,r:type==='brute'?22:type==='wisp'?13:17,hp:(type==='brute'?42:type==='wisp'?13:24)*scale,maxHp:(type==='brute'?42:type==='wisp'?13:24)*scale,speed:(type==='brute'?45:type==='wisp'?82:57)+Math.min(wave,9)*2,damage:(type==='brute'?12:8)+Math.floor(wave/4),type,attack:rand(.3,1.3),hit:0,phase:rand(0,6.28),flash:0})}
function startWave(){wave++;bestWave=Math.max(bestWave,wave-1);spawnLeft=Math.min(3+wave,9);spawnTimer=.8;waveWait=0;showMessage(`NIGHT ${String(wave).padStart(2,'0')} · THE DARK GROWS`);player.hp=Math.min(player.maxHp,player.hp+Math.max(12,player.maxHp*.18));updateUI();saveGame()}
function addParticles(x,y,color,count=9,power=120){for(let i=0;i<count;i++){const a=rand(0,Math.PI*2),v=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.25,.65),max:.65,size:rand(2,5),color})}}
function killEnemy(e){const idx=enemies.indexOf(e);if(idx<0)return;enemies.splice(idx,1);kills++;score+=e.type==='brute'?35:e.type==='wisp'?15:22;player.damage+=1;player.maxHp+=4;player.hp=Math.min(player.maxHp,player.hp+14);if(kills%5===0)player.speed+=4;xp++;if(xp>=level*5){xp=0;level++;player.maxHp+=10;player.hp=Math.min(player.maxHp,player.hp+20);showMessage(`LEVEL ${level} · THE LANTERN BURNS BRIGHTER`)}else showMessage('+1 DAMAGE  ·  +4 VITALITY  ·  +14 HEAL');addParticles(e.x,e.y,e.type==='brute'?'#f0bd73':'#c3d89c',15,180);tone(680,.09,'sine',.04);updateUI();saveGame()}
function attack(){if(gameOver||paused||attackCooldown>0)return;attackCooldown=.36;swing=.22;swingHit=false;tone(190,.08,'triangle',.035)}
function tryDash(){if(gameOver||paused||dashCooldown>0)return;let dx=0,dy=0;for(const k of keys){if(k==='w'||k==='arrowup')dy--;if(k==='s'||k==='arrowdown')dy++;if(k==='a'||k==='arrowleft')dx--;if(k==='d'||k==='arrowright')dx++}if(!dx&&!dy){dx=Math.cos(player.dir);dy=Math.sin(player.dir)}const len=Math.hypot(dx,dy)||1;player.dir=Math.atan2(dy,dx);dashTime=.19;dashCooldown=3.5;player.vx=dx/len;player.vy=dy/len;player.invuln=.4;addParticles(player.x,player.y,'#d7c37f',10,95);tone(370,.13,'sine',.04)}
function tone(freq,duration,type='sine',volume=.03){if(!soundOn)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}

