for(let i=0;i<42;i++){const edge=i/41;const x=edge*W;for(const y of [8,532])drawBush(x+rand(-9,9),y+rand(-6,7),rand(15,35));const yy=30+edge*(H-60);for(const xx of [8,952])drawBush(xx+rand(-8,8),yy+rand(-9,9),rand(16,31))}for(const [x,y] of [[86,250],[865,285],[280,45],[728,495]]){const glow=ctx.createRadialGradient(x,y,1,x,y,45);glow.addColorStop(0,'#e3bd6e29');glow.addColorStop(1,'#e3bd6e00');ctx.fillStyle=glow;ctx.fillRect(x-45,y-45,90,90);ctx.fillStyle='#d1a85d';ctx.beginPath();ctx.arc(x,y,2.4,0,7);ctx.fill()}const vignette=ctx.createRadialGradient(480,270,120,480,270,590);vignette.addColorStop(0,'#111a1600');vignette.addColorStop(1,'#0c14128c');ctx.fillStyle=vignette;ctx.fillRect(0,0,W,H)}
