function drawPlayer(){if(!player)return;const x=player.x,y=player.y;ctx.save();if(player.invuln>0&&Math.floor(performance.now()/70)%2===0)ctx.globalAlpha=.55;ctx.fillStyle='#10181280';ctx.beginPath();ctx.ellipse(x,y+13,18,8,0,0,7);ctx.fill();if(swing>0){const progress=1-swing/.22;ctx.strokeStyle=`rgba(241,218,156,${.8*(1-progress)})`;ctx.lineWidth=5;ctx.beginPath();ctx.arc(x,y,68,player.dir-1.42+progress*1.8,player.dir+.35+progress*1.8);ctx.stroke();ctx.strokeStyle='#fff4c2';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,73,player.dir-1.3+progress*1.8,player.dir+.15+progress*1.8);ctx.stroke()}ctx.save();ctx.translate(x,y);ctx.rotate(player.dir);if(dashTime>0){ctx.globalAlpha=.45;ctx.fillStyle='#d9d092';ctx.beginPath();ctx.ellipse(-22,0,26,12,0,0,7);ctx.fill();ctx.globalAlpha=1}ctx.fillStyle='#75805d';ctx.beginPath();ctx.moveTo(-14,-10);ctx.lineTo(9,-12);ctx.lineTo(16,10);ctx.lineTo(-8,13);ctx.closePath();ctx.fill();ctx.fillStyle='#a7a47b';ctx.beginPath();ctx.arc(2,-1,10,0,7);ctx.fill();ctx.fillStyle='#d9c696';ctx.beginPath();ctx.arc(8,-7,7,0,7);ctx.fill();ctx.fillStyle='#34423a';ctx.beginPath();ctx.arc(11,-8,5.5,-.4,Math.PI*1.2);ctx.fill();ctx.fillStyle='#e8cc8c';ctx.beginPath();ctx.moveTo(5,3);ctx.lineTo(30,0);ctx.lineTo(6,5);ctx.fill();ctx.strokeStyle='#eee1b9';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(8,3);ctx.lineTo(28,0);ctx.stroke();ctx.fillStyle='#ddaa55';ctx.shadowColor='#ffd477';ctx.shadowBlur=10;ctx.beginPath();ctx.arc(-8,5,3.3,0,7);ctx.fill();ctx.restore();ctx.restore()}
function drawEnemy(e){const bob=Math.sin(e.phase)*3;ctx.save();ctx.translate(e.x,e.y+bob);ctx.fillStyle='#0c131280';ctx.beginPath();ctx.ellipse(0,e.r*.75,e.r*1.1,e.r*.48,0,0,7);ctx.fill();let col=e.type==='brute'?'#777258':e.type==='wisp'?'#859776':'#758879';if(e.flash>0)col='#f5e8bd';ctx.shadowColor=e.type==='wisp'?'#bfd896':'#a2c39b';ctx.shadowBlur=e.type==='brute'?9:17;ctx.fillStyle=col;ctx.beginPath();if(e.type==='wisp'){ctx.arc(0,0,e.r,0,7)}else{ctx.moveTo(-e.r,-e.r*.35);ctx.quadraticCurveTo(-e.r*1.05,-e.r*1.35,0,-e.r);ctx.quadraticCurveTo(e.r*1.2,-e.r*.75,e.r,e.r*.25);ctx.lineTo(e.r*.45,e.r*.7);ctx.lineTo(0,e.r*.35);ctx.lineTo(-e.r*.45,e.r*.8);ctx.closePath()}ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#e7dca8';ctx.beginPath();ctx.arc(-e.r*.3,-e.r*.12,e.type==='brute'?2.5:2,0,7);ctx.arc(e.r*.3,-e.r*.12,e.type==='brute'?2.5:2,0,7);ctx.fill();if(e.hp<e.maxHp){ctx.fillStyle='#111812b0';rounded(-e.r,-e.r-10,e.r*2,3,2);ctx.fill();ctx.fillStyle='#d67d63';rounded(-e.r,-e.r-10,e.r*2*clamp(e.hp/e.maxHp,0,1),3,2);ctx.fill()}ctx.restore()}
function draw(){if(!ctx)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2),cw=Math.max(1,Math.floor(rect.width*dpr)),ch=Math.max(1,Math.floor(rect.height*dpr));if(canvas.width!==cw||canvas.height!==ch){canvas.width=cw;canvas.height=ch}ctx.setTransform(cw/W,0,0,ch/H,0,0);drawGround();for(const e of enemies)drawEnemy(e);drawPlayer();for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,7);ctx.fill()}ctx.globalAlpha=1;if(flash>0){ctx.fillStyle=`rgba(205,83,63,${flash*1.3})`;ctx.fillRect(0,0,W,H)}if(!enemies.length&&!spawnLeft&&!gameOver){ctx.globalAlpha=.65;ctx.fillStyle='#e7d8aa';ctx.beginPath();ctx.arc(480,270,32+Math.sin(performance.now()*.003)*5,0,7);ctx.fill();ctx.globalAlpha=1}}

