60:function update(dt){if(!player||paused||gameOver)return;elapsed+=dt;attackCooldown=Math.max(0,attackCooldown-dt);dashCooldown=Math.max(0,dashCooldown-dt);swing=Math.max(0,swing-dt);player.invuln=Math.max(0,player.invuln-dt);flash=Math.max(0,flash-dt);if(msgTimer>0&&(msgTimer-=dt)<=0)ui.msg.classList.remove('show');let dx=0,dy=0;for(const k of keys){if(k==='w'||k==='arrowup')dy--;if(k==='s'||k==='arrowdown')dy++;if(k==='a'||k==='arrowleft')dx--;if(k==='d'||k==='arrowright')dx++}for(const d of heldDirs){if(d==='up')dy--;if(d==='down')dy++;if(d==='left')dx--;if(d==='right')dx++}if(dx||dy){const n=Math.hypot(dx,dy);dx/=n;dy/=n;player.dir=Math.atan2(dy,dx)}const moveSpeed=dashTime>0?570:player.speed;if(dashTime>0)dashTime=Math.max(0,dashTime-dt);player.x=clamp(player.x+(dashTime>0?player.vx:dx)*moveSpeed*dt,35,W-35);player.y=clamp(player.y+(dashTime>0?player.vy:dy)*moveSpeed*dt,40,H-35);if(keys.has(' ')||keys.has('space'))attack();if(swing>0&&!swingHit){for(const e of [...enemies]){const d=Math.hypot(e.x-player.x,e.y-player.y);if(d<115+e.r){const a=Math.atan2(e.y-player.y,e.x-player.x),diff=Math.atan2(Math.sin(a-player.dir),Math.cos(a-player.dir));if(Math.abs(diff)<1.65){e.hp-=player.damage;e.flash=.15;addParticles(e.x,e.y,'#e7d59b',5,90);if(e.hp<=0)killEnemy(e);else tone(310,.04,'square',.02)}}}swingHit=true}for(const e of [...enemies]){e.phase+=dt*2;e.hit=Math.max(0,e.hit-dt);e.flash=Math.max(0,e.flash-dt);e.attack-=dt;const vx=player.x-e.x,vy=player.y-e.y,d=Math.hypot(vx,vy)||1;if(d>player.r+e.r+8){e.x+=vx/d*e.speed*dt;e.y+=vy/d*e.speed*dt}else if(e.attack<=0&&player.invuln<=0){e.attack=e.type==='brute'?1.5:1.15;player.hp-=e.damage;player.invuln=.45;flash=.16;addParticles(player.x,player.y,'#e9846a',7,100);tone(120,.12,'sawtooth',.04);if(player.hp<=0){player.hp=0;endRun();break}}}for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);if(spawnLeft>0){spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy();spawnLeft--;spawnTimer=Math.max(.48,1.3-wave*.045)}}else if(enemies.length===0){waveWait+=dt;if(waveWait>2.2)startWave()}if(elapsed-autosaveAt>4){autosaveAt=elapsed;saveGame()}updateUI()}
